"""Job scheduler for data ingestion pipelines."""

import logging
import time
from typing import Any, Callable

logger = logging.getLogger(__name__)

# Registry of named jobs
_jobs: dict[str, Any] = {}


class Job:
    def __init__(self, name: str, func: Callable[..., Any], interval_seconds: int = 60) -> None:
        self.name: str = name
        self.func: Callable[..., Any] = func
        self.interval_seconds: int = interval_seconds
        self.last_run: float = 0.0
        self.enabled: bool = True

    def run(self) -> None:
        self.func()
        self.last_run = time.time()

    def schedule(self) -> None:
        """Start the job scheduler."""
        while self.enabled:
            now = time.time()
            if now - self.last_run >= self.interval_seconds:
                self.run()
            time.sleep(1)


def init_scheduler(jobs: list[dict[str, Any]]) -> None:
    """Initialize the scheduler with a list of job configs."""
    for job_config in jobs:
        name = job_config.get("name")
        func = job_config.get("func")
        interval = job_config.get("interval_seconds", 60)
        if name and func:
            _jobs[name] = Job(name, func, interval)


def get_job(name: str) -> Job | None:
