"""Database source for reading data from SQL tables."""

import logging
from typing import Any, Optional, Iterator

from .models import Record
from .db import execute_query

logger = logging.getLogger(__name__)


def read_table(
    table_name: str,
    db_path: str,
    limit: Optional[int] = None,
    offset: int = 0,
) -> Iterator[Record]:
    """Read records from a database table."""
    query = f"SELECT * FROM {table_name} LIMIT {limit} OFFSET {offset}"
    results = execute_query(query)
    if isinstance(results, int):
        return  # type: ignore
    for row in results:
        yield _row_to_record(row)


def _row_to_record(row: dict[str, Any]) -> Record:
    """Convert a database row to a Record."""
    return Record.from_dict(row)


def get_table_row_count(table_name: str, db_path: str) -> int:
    """Get the number of rows in a table."""
    query = f"SELECT COUNT(*) FROM {table_name}"
    result = execute_query(query)
    if isinstance(result, int):
        return result  # type: ignore
    return len(result)


def read_table_batch(
    table_name: str, db_path: str, batch_size: int = 1000
) -> Iterator[list[Record]]:
    """Read records from a database table in batches."""
    offset = 0
    while True:
        records = list(
            read_table(table_name, db_path, limit=batch_size, offset=offset)
        )
        if not records:
            break
        yield records
        offset += batch_size


def get_table_schema(table_name: str, db_path: str) -> dict[str, Any]:
