    table_name: str, db_path: str, batch_size: int = 1000
) -> Iterator[list[Record]]:
    """Read records from a database table in batches."""
    offset = 0
    while True:
        records = list(
            read_table(table_name, db_path, limit=batch_size, offset=offset)
        )
        if not records:
            break
        yield records
        offset += batch_size


